ALTER TABLE item_master ADD COLUMN display_name text;
ALTER TABLE item_master ADD COLUMN item_group text NOT NULL DEFAULT 'Costing reference';
UPDATE item_master SET display_name=key;
ALTER TABLE item_master ALTER COLUMN display_name SET NOT NULL;
CREATE TABLE item_spec_versions (
 key text NOT NULL REFERENCES item_master(key),version integer NOT NULL CHECK(version>0),
 specification text, status text NOT NULL CHECK(status IN ('Need to enter','Approved','Needs review')),
 notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),created_by uuid REFERENCES users(id),
 PRIMARY KEY(key,version),CHECK(status <> 'Approved' OR length(trim(specification))>0)
);
CREATE TRIGGER immutable_specs BEFORE UPDATE OR DELETE ON item_spec_versions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
